    val results = queryFlow.flatMapLatest { query ->
        flow<Unit> {
            try {
                awaitCancellation()
            } finally {
                cancelledQueries += query
            }
        }
    }
    backgroundScope.launch { results.collect() }
    runCurrent() // Subscribe before a replay-zero flow emits.

